/**
 * Blurred placeholders, inlined.
 *
 * An 18-pixel-wide blurred WebP of each plate, around a hundred bytes apiece.
 * They sit behind the real image as a `background-image`, so a plate is never
 * an empty rectangle: while the photograph decodes, and in the rare case it
 * never arrives — a slow connection, a lazy image below a fold that nobody
 * scrolled to — what shows is a recognisable blur of the same frame rather
 * than a void.
 *
 * Total cost: 394 bytes, and no request — every one of these is generated by
 * resizing the real asset to 18 pixels wide and blurring it, never hand-typed.
 */
export const PLACEHOLDERS = {
  forest:
    'data:image/webp;base64,UklGRkwAAABXRUJQVlA4IEAAAADwAwCdASoSAAoAPxFysVAsJqSisAgBgCIJYwC/OCIjvzvuMxlVqcgAAP2wFUFjW+3Iysv/HYxwd3TzcZtjAAAA',
  deku: 'data:image/webp;base64,UklGRlAAAABXRUJQVlA4IEQAAAAwAwCdASoSAAoAPxFysVCsJqSisAgBgCIJQBkTAw7evH0AAP6ilJDRe9Kpksy2oFvd0MGbKCiv0uH2NhKm877YF6cAAA==',
  epona:
    'data:image/webp;base64,UklGRkoAAABXRUJQVlA4ID4AAABwAwCdASoSAAoAPxFysFAsJqSisAgBgCIJQBWAAm7AkA6ay4AA/m70OxMmyJb7zBLNMLrHrDNiNaYbjNAAAA==',
  poster:
    'data:image/webp;base64,UklGRoQAAABXRUJQVlA4IHgAAAAwBQCdASoSACcAPwFmqlArJSOiurZoAWAgCUAXYAIgrLCaXI00aYzsj4rxBZokk8bmAAD8XMPObtfijbn9KQym2znF59yYGM0ZuIczzqhgmoII9YT84CLvONoe1oH9+l22x0ngldjfrQqqlKNs0/0vRez7TtAAAAA=',
} as const

/**
 * Ready to drop into a `background-image`. Sizing and positioning live in the
 * consuming rule — a shorthand like `url() center / cover` is not a valid
 * `background-image` value and the browser drops the whole declaration.
 */
export function placeholder(key: keyof typeof PLACEHOLDERS): string {
  return `url("${PLACEHOLDERS[key]}")`
}
